    else:
        # On Unix, remove all permissions
        dotenv_path.chmod(0o000)

    try:
        with pytest.raises(PermissionError):
            dotenv.set_key(dotenv_path, "a", "b")

        assert list(dotenv_path.parent.glob(".tmp_*")) == []
