        stop=tenacity.stop_after_attempt(3),
        retry=tenacity.retry_if_exception_type(ValueError),
        reraise=True,
    )
    def _foobar() -> int:
        attempts.append(_foobar.retry.statistics["attempt_number"])
        if len(attempts) < 3:
            raise ValueError("retry")
        return 42

    _foobar()
    self.assertEqual(attempts, [1, 2, 3])

