@cli.command(
    context_settings={
        "allow_extra_args": True,
        "allow_interspersed_args": False,
        "ignore_unknown_options": True,
    }
)
@click.pass_context
@click.option(
    "--override/--no-override",
    default=True,
    help="Override variables from the environment file with those from the .env file.",
)
@click.argument("commandline", nargs=-1, type=click.UNPROCESSED)
def run(ctx: click.Context, override: bool, commandline: tuple[str, ...]) -> None:
    """Run command with environment variables present."""
    file = ctx.obj["FILE"]
    if not os.path.isfile(file):
        raise click.BadParameter(
            f"Invalid value for '-f' \"{file}\" does not exist.", ctx=ctx
        )
    dotenv_as_dict = {
        k: v
        for (k, v) in DotEnv(file, override=override, encoding="utf-8").dict().items()
        if v is not None and (override or k not in os.environ)
    }

    if not commandline:
        click.echo("No command given.")
        sys.exit(1)

    run_command([*commandline, *ctx.args], dotenv_as_dict)

def write(self, data):
    if self._closed:
        raise ValueError('I/O operation on closed storage')

    # Store data in cache
    self.cache = data
    self._cache_modified_count += 1

    # Check if we need to flush the cache
    if self._cache_modified_count >= self.WRITE_CACHE_SIZE:
        self.flush()

def flush(self):
    """
    Flush all unwritten data to disk.
    """
    if self._closed:
        raise ValueError('I/O operation on closed storage')

    if self._cache_modified_count > 0:
        # Force-flush the cache by writing the data to the storage
        self.storage.write(self.cache)
        self._cache_modified_count = 0

def _run_job(self, job: "Job") -> None:
    ret = job.run()
    if isinstance(ret, CancelJob) or ret is CancelJob:
        self.cancel_job(job)

@property
def idle_seconds(self) -> Optional[float]:
    """
    :return: Number of seconds until
             :meth:`next_run <Scheduler.next_run>`
             or None if no jobs are scheduled
    """
    if not self.next_run:
        return None
    return (self.next_run - datetime.datetime.now()).total_seconds()

def __contains__(self, key):
    try:
        link = self.__links[key]  # no reordering
    except KeyError:
        return False
    else:
        return self.timer() < link.expires

@property
def timer(self):
    """The timer function used by the cache."""
    return self.__timer

def __delitem__(self, key, cache_delitem=Cache.__delitem__):
    cache_delitem(self, key)
    link = self.__links.pop(key)
    link.unlink()
    if not (self.timer() < link.expires):
        raise KeyError(key)

def __getitem__(self, key, cache_getitem=Cache.__getitem__):
    try:
        link = self.__getlink(key)
    except KeyError:
        expired = False
    else:
        expired = not (self.timer() < link.expires)
    if expired:
        return self.__missing__(key)
    else:
        return cache_getitem(self, key)

class _Link:
    __slots__ = ("expires", "key", "next", "prev")

    def __init__(self, key=None, expires=None):
        self.key = key
        self.expires = expires

    def __reduce__(self):
        return TTLCache._Link, (self.key, self.expires)

    def unlink(self):
        next = self.next
        prev = self.prev
        prev.next = next
        next.prev = prev

def get_environ_proxies(url, no_proxy=None):
    """
    Return a dict of environment proxies.

    :rtype: dict
    """
    if should_bypass_proxies(url, no_proxy=no_proxy):
        return {}
    else:
        return getproxies()

def should_bypass_proxies(url, no_proxy):
    """
    Returns whether we should bypass proxies or not.

    :rtype: bool
    """

    # Prioritize lowercase environment variables over uppercase
    # to keep a consistent behaviour with other http projects (curl, wget).
    def get_proxy(key):
        return os.environ.get(key) or os.environ.get(key.upper())

    # First check whether no_proxy is defined. If it is, check that the URL
    # we're getting isn't in the no_proxy list.
    no_proxy_arg = no_proxy
    if no_proxy is None:
        no_proxy = get_proxy("no_proxy")
    parsed = urlparse(url)

    if parsed.hostname is None:
        # URLs don't always have hostnames, e.g. file:/// urls.
        return True

    if no_proxy:
        # We need to check whether we match here. We need to see if we match
        # the end of the hostname, both with and without the port.
        no_proxy = (host for host in no_proxy.replace(" ", "").split(",") if host)

        if is_ipv4_address(parsed.hostname):
            for proxy_ip in no_proxy:
                if is_valid_cidr(proxy_ip):
                    if address_in_network(parsed.hostname, proxy_ip):
                        return True
                elif parsed.hostname == proxy_ip:
                    # If no_proxy ip was defined in plain IP notation instead of cidr notation &
                    # matches the IP of the index
                    return True
        else:
            host_with_port = parsed.hostname
            if parsed.port:
                host_with_port += f":{parsed.port}"

            for host in no_proxy:
                if parsed.hostname.endswith(host) or host_with_port.endswith(host):
                    # The URL does match something in no_proxy, so we don't want
                    # to apply the proxies on this URL.
                    return True

    with set_environ("no_proxy", no_proxy_arg):
        # parsed.hostname can be `None` in cases such as a file URI.
        try:
            bypass = proxy_bypass(parsed.hostname)
        except (TypeError, socket.gaierror):
            bypass = False

    if bypass:
        return True

    return False

